import placesJson from '../../data/places.json';
import classesJson from '../../data/classes.json';
import ratingsJson from '../../data/ratings.json';
/**
 * SANDBOX D: realistic demo data. The source is d/data/*.json (generated by
 * d/scripts/generate-data.mjs): 40 fictional places in Berlin, ~100 classes for one day,
 * 500 past ratings. This file maps that JSON into the class model every screen already uses,
 * so the Energy Match card, filters, sort, card, booking and rating keep working.
 *
 * Everything is fictional: places, streets, trainers and comments. Photos are free stock photos.
 *
 * Research IDs (see docs/research.md) are noted next to each field group.
 */

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type ClassType =
  | 'yoga'
  | 'pilates'
  | 'hiit'
  | 'spinning'
  | 'dance'
  | 'swimming'
  | 'boxing'
  | 'gym'
  | 'climbing'
  | 'wellness';

/** 1 = very easy … 5 = very hard */
export type Intensity = 1 | 2 | 3 | 4 | 5;

/** 1 = quiet background … 5 = club-loud */
export type Volume = 1 | 2 | 3 | 4 | 5;

/** 1 = very relaxed … 5 = very strict */
export type TrainerStyle = 1 | 2 | 3 | 4 | 5;

export type Busyness = 'calm' | 'moderate' | 'busy';
export type RoomSize = 'small' | 'medium' | 'spacious';
export type LightLevel = 'dim' | 'natural' | 'bright' | 'flashing';
export type PartnerWork = 'none' | 'optional' | 'required';

export interface Facilities {
  // Research: F-FACILITIES (showers incl. private, lockers, safe box, space to change)
  showers: 'private' | 'shared' | 'shared-and-private' | 'none';
  lockers: 'free' | 'bring-padlock' | 'none';
  safeBox: boolean;
  changingRoom: { crowding: 'roomy' | 'gets-busy' | 'tight'; note?: string };
  towels: 'free' | 'rent' | 'bring';
}

export type PlaceType = 'yoga' | 'pilates' | 'gym' | 'dance' | 'boxing' | 'climbing' | 'swimming' | 'wellness';
export type Noise = 'quiet' | 'medium' | 'loud';
export type Light = 'soft' | 'normal' | 'bright' | 'flashing';
export type Crowd = 'small' | 'medium' | 'large';
export type ClassIntensity = 'gentle' | 'moderate' | 'hard';

/** Room traits of a place (d/data/places.json) */
export interface RoomTraits { noise: Noise; light: Light; crowd: Crowd; partnerWork: 'yes' | 'no' }

export interface Studio {
  id: string;
  name: string;
  district: string;
  address: string;
  type: PlaceType;
  description: string;
  photo: string;
  traits: RoomTraits;
  /** demo: extra distance inside the district (see lib/location.ts) */
  offsetKm: number;
  // Research: F-LOCATION (location stops 8/22 from booking). DEMO: from the fixed demo location, Kreuzberg.
  distanceKm: number;
  travelMin: number;
  facilities: Facilities;
}

export interface FlowStep {
  name: string;
  minutes: number;
  intensity: Intensity;
}

export interface ExpectInfo {
  // Research: F-CROWD (dealbreaker for 9/22, #1 reason to leave)
  crowd: {
    typicalMin: number;
    typicalMax: number;
    capacity: number;
    roomSize: RoomSize;
    busyness: Busyness;
    note?: string;
  };
  // Research: F-CLEAN (strongest dealbreaker, 10/22)
  // PRD: "never guess": null = not described yet
  clean: {
    lastCleaned: string;
    /** Member rating 1–5, one decimal. null = not enough ratings yet */
    rating: number | null;
    ventilation: string | null;
    temperature: string | null;
  };
  // Research: F-LEVEL (labels are not honest)
  level: {
    official: string;
    reality: string;
    priorKnowledge: string;
    /** % of first-timers who said the level matched the label */
    firstTimerMatchPct: number;
  };
  // Research: F-SOUND
  /** mic: null = not described yet */
  sound: { volume: Volume; mic: boolean | null; note?: string };
  // Research: F-LIGHT
  light: { level: LightLevel; note?: string };
  // Research: F-TRAINER
  trainer: {
    style: TrainerStyle;
    handsOn: boolean;
    /** null when the trainer doesn't do hands-on corrections at all */
    asksBeforeTouch: boolean | null;
    note?: string;
  };
  // Research: F-PARTNER
  partner: { work: PartnerWork; note?: string };
  // Research: F-FLOW
  flow: FlowStep[];
  // Research: F-BRING
  bring: string[];
  arrival: string;
  // Research: F-SOCIAL
  leaving: { quietExitOk: boolean; note: string };
  social: string[];
  // PRD: "quiet space" field (a place to step out or arrive calmly). null = not described yet
  quietSpace: string | null;
}

export interface ClassInfo {
  id: string;
  studioId: string;
  name: string;
  type: ClassType;
  /** 24h "HH:MM", all classes are "today" in the prototype */
  start: string;
  durationMin: number;
  trainer: string;
  // Research: F-VIBE (atmosphere is the top factor, 18/22)
  vibe: string;
  /** Anonymous member answers from the last 30 days the card is based on (PRD: name the sources) */
  reports: number;
  /** Does the studio's own checklist exist for this class? (PRD: studio checklist + member answers) */
  studioChecklist: boolean;
  /** PRD: when recent feedback differs from the description, e.g. "Recently reported as louder" */
  recentReport?: string;
  /** D: plain intensity and the 2–3 "What to expect" lines from d/data/classes.json */
  intensity: ClassIntensity;
  whatToExpect: string[];
  /** D: 2–3 sentences about the class (what you do, for whom, how it feels) */
  description: string;
  expect: ExpectInfo;
}

// ---------------------------------------------------------------------------
// D: places and classes from d/data/*.json
// ---------------------------------------------------------------------------

interface PlaceJson { id: string; name: string; type: PlaceType; district: string; address: string; description: string; photo: string; traits: RoomTraits; offsetKm: number }
interface ClassJson { id: string; placeId: string; name: string; type: ClassType; start: string; durationMin: number; intensity: ClassIntensity; trainer: string; whatToExpect: string[]; touch: 'none' | 'asks-first' | 'hands-on'; description: string }
interface RatingJson { classId: string; matchedCard: 'yes' | 'partly' | 'no'; answers: { noise: Noise; crowd: Crowd } }

const PLACES = placesJson as PlaceJson[];
const CLASSES = classesJson as ClassJson[];
const RATINGS = ratingsJson as RatingJson[];

/** Facilities by place type (demo). */
const FACILITIES: Record<PlaceType, Facilities> = {
  yoga: { showers: 'shared', lockers: 'free', safeBox: true, changingRoom: { crowding: 'roomy' }, towels: 'free' },
  pilates: { showers: 'shared-and-private', lockers: 'free', safeBox: true, changingRoom: { crowding: 'roomy' }, towels: 'free' },
  gym: { showers: 'shared', lockers: 'bring-padlock', safeBox: false, changingRoom: { crowding: 'gets-busy', note: 'Busy after evening classes' }, towels: 'rent' },
  dance: { showers: 'shared', lockers: 'free', safeBox: false, changingRoom: { crowding: 'gets-busy' }, towels: 'bring' },
  boxing: { showers: 'shared', lockers: 'bring-padlock', safeBox: false, changingRoom: { crowding: 'tight' }, towels: 'bring' },
  climbing: { showers: 'shared', lockers: 'free', safeBox: true, changingRoom: { crowding: 'roomy' }, towels: 'rent' },
  swimming: { showers: 'shared', lockers: 'free', safeBox: true, changingRoom: { crowding: 'gets-busy', note: 'Shower before the pool' }, towels: 'rent' },
  wellness: { showers: 'shared-and-private', lockers: 'free', safeBox: true, changingRoom: { crowding: 'roomy' }, towels: 'free' },
};

const BRING: Record<PlaceType, string[]> = {
  yoga: ['Comfortable clothes', 'Mats and towels are provided'],
  pilates: ['Grip socks', 'Comfortable clothes', 'Towel (or rent one)'],
  gym: ['Indoor trainers', 'Towel', 'Water bottle', 'Padlock for the locker'],
  dance: ['Socks or bare feet', 'Comfortable clothes', 'Water bottle'],
  boxing: ['Indoor trainers', 'Towel', 'Water bottle', 'Hand wraps (or borrow)'],
  climbing: ['Comfortable clothes', 'Climbing shoes (or rent)', 'Water bottle'],
  swimming: ['Swimwear', 'Swim cap', 'Goggles', 'Flip-flops', 'Towel (or rent one)'],
  wellness: ['Two towels (or rent them)', 'Flip-flops', 'Water bottle'],
};

const PEAK: Record<ClassIntensity, Intensity> = { gentle: 2, moderate: 3, hard: 5 };
const VOLUME: Record<Noise, Volume> = { quiet: 1, medium: 3, loud: 5 };
const LIGHTS: Record<Light, LightLevel> = { soft: 'dim', normal: 'natural', bright: 'bright', flashing: 'flashing' };
const CROWDS: Record<Crowd, ExpectInfo['crowd']> = {
  small: { typicalMin: 4, typicalMax: 8, capacity: 10, roomSize: 'small', busyness: 'calm' },
  medium: { typicalMin: 10, typicalMax: 16, capacity: 20, roomSize: 'medium', busyness: 'moderate' },
  large: { typicalMin: 18, typicalMax: 28, capacity: 30, roomSize: 'spacious', busyness: 'busy' },
};
const LEVEL: Record<ClassIntensity, string> = { gentle: 'All levels', moderate: 'Open level', hard: 'Intermediate' };

export const studios: Studio[] = PLACES.map((p) => {
  return {
    id: p.id, name: p.name, district: p.district, address: p.address,
    type: p.type, description: p.description, photo: p.photo, traits: p.traits, offsetKm: p.offsetKm,
    // Distances from Kreuzberg (the default place); other places in lib/location.ts
    distanceKm: 0, travelMin: 0,
    facilities: FACILITIES[p.type],
  };
});

function toClass(j: ClassJson): ClassInfo {
  const p = PLACES.find((x) => x.id === j.placeId)!;
  const t = p.traits;
  const rs = RATINGS.filter((r) => r.classId === j.id);
  const peak = PEAK[j.intensity];
  const third = Math.round(j.durationMin / 6);
  return {
    id: j.id, studioId: j.placeId, name: j.name, type: j.type, start: j.start, durationMin: j.durationMin,
    trainer: j.trainer, vibe: j.whatToExpect[0], reports: rs.length, studioChecklist: true,
    intensity: j.intensity, whatToExpect: j.whatToExpect, description: j.description,
    expect: {
      crowd: { ...CROWDS[t.crowd], note: j.whatToExpect[2] },
      clean: { lastCleaned: 'Cleaned every day', rating: rs.length >= 5 ? Math.round((4 + (j.id.length % 8) / 10) * 10) / 10 : null, ventilation: t.noise === 'quiet' ? 'Open windows' : 'Air system', temperature: p.type === 'wellness' ? 'Warm, sauna up to 90 °C' : null },
      level: {
        official: LEVEL[j.intensity], reality: j.whatToExpect[0], priorKnowledge: j.intensity === 'hard' ? 'Some experience helps' : 'None',
        firstTimerMatchPct: rs.length ? Math.round((rs.filter((r) => r.matchedCard === 'yes').length / rs.length) * 100) : 80,
      },
      sound: { volume: VOLUME[t.noise], mic: t.noise === 'loud', note: j.whatToExpect[1] },
      light: { level: LIGHTS[t.light] },
      // Touch per class (d/data/classes.json): feeds "Touch only if I agree"
      trainer: { style: j.intensity === 'hard' ? 4 : j.intensity === 'moderate' ? 3 : 2, handsOn: j.touch !== 'none', asksBeforeTouch: j.touch === 'none' ? null : j.touch === 'asks-first' },
      partner: { work: t.partnerWork === 'yes' ? 'required' : 'none' },
      flow: [
        { name: 'Warm-up', minutes: third, intensity: Math.max(1, peak - 2) as Intensity },
        { name: 'Main part', minutes: j.durationMin - 2 * third, intensity: peak },
        { name: 'Cool-down', minutes: third, intensity: 1 },
      ],
      bring: BRING[p.type],
      arrival: p.type === 'swimming' ? '15 min early, shower before the pool' : '10 min early',
      leaving: { quietExitOk: t.noise !== 'loud', note: t.noise !== 'loud' ? 'Fine to step out quietly' : 'Doors at the back, fine to step out' },
      social: [],
      quietSpace: p.type === 'wellness' || p.type === 'yoga' ? 'A quiet rest area by the entrance' : null,
    },
  };
}

export const classes: ClassInfo[] = CLASSES.map(toClass);

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** "07:30" → 450. Times are compared as real times, not as text. */
export function toMinutes(t: string): number {
  const [h, m] = t.split(':').map(Number);
  return h * 60 + m;
}

/** Earliest start first. */
export const byStart = (a: ClassInfo, b: ClassInfo) => toMinutes(a.start) - toMinutes(b.start);

export function getClass(id: string): ClassInfo | undefined {
  return classes.find((c) => c.id === id);
}

export function getStudio(id: string): Studio {
  const s = studios.find((st) => st.id === id);
  if (!s) throw new Error(`Unknown studio: ${id}`);
  return s;
}

export function endTime(c: ClassInfo): string {
  const [h, m] = c.start.split(':').map(Number);
  const total = h * 60 + m + c.durationMin;
  return `${String(Math.floor(total / 60) % 24).padStart(2, '0')}:${String(total % 60).padStart(2, '0')}`;
}
